using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ApiTools
{
    [McpServerTool(Name = "fetch_data"), Description("Fetches data from an external API by path.")]
    public static async Task<string> FetchDataAsync(
        IHttpClientFactory httpClientFactory,
        [Description("The API resource path to fetch (e.g. \"/users/1\").")] string path,
        CancellationToken cancellationToken)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");

        using var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync(cancellationToken), cancellationToken: cancellationToken);

        return JsonSerializer.Serialize(doc.RootElement, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizationPrompts
{
    [McpServerPrompt(Name = "summarize"), Description("Summarizes the provided text into key points.")]
    public static GetPromptResult Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Maximum number of bullet points (default: 5).")] int? maxPoints = 5)
    {
        return new GetPromptResult
        {
            Description = "Summarize the following text",
            Messages =
            [
                new PromptMessage
                {
                    Role = Role.User,
                    Content = new TextContentBlock
                    {
                        Text = $"""
                            Summarize the following text into at most {maxPoints ?? 5} concise bullet points.
                            Return only the bullet points, no preamble.

                            Text:
                            {text}
                            """
                    }
                }
            ]
        };
    }
}

