using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizationPrompts
{
    [McpServerPrompt(Name = "summarize"), Description("Summarizes the provided text into key points.")]
    public static GetPromptResult Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Maximum number of bullet points (default: 5).")] int? maxPoints = 5)
    {
        return new GetPromptResult
        {
            Description = "Summarize the following text",
            Messages =
            [
                new PromptMessage
                {
                    Role = Role.User,
                    Content = new TextContentBlock
                    {
                        Text = $"""
                            Summarize the following text into at most {maxPoints ?? 5} concise bullet points.
                            Return only the bullet points, no preamble.

                            Text:
                            {text}
                            """
                    }
                }
            ]
        };
    }
}

